// test_driver.cpp — end-to-end tests for the sturm-transpile binary.
//
// These are integration tests: they spawn the freshly built binary and
// check its observable behavior:
//   1. `sturm-transpile --version` prints a version line and exits 0.
//   2. `sturm-transpile <hello.cpp> --output-dir <tmp>` produces a
//      transpiled file at <tmp>/hello.cpp. At M9 the driver always runs
//      the full pipeline for non-skip files, which prepends the
//      AUTO-GENERATED header even when no quantum ops were matched.
//   3. A missing input file causes a non-zero exit.
//   4. Already-generated files (whose first non-blank line is the
//      AUTO-GENERATED sentinel) are copied verbatim — proves idempotency.
//
// The CMake wiring passes the absolute path to the compiled binary as a
// preprocessor macro STURM_TRANSPILE_BIN. We do not hard-code a path; the
// test must work regardless of build-tree layout.

#include <cassert>
#include <cstdio>
#include <cstdlib>
#include <filesystem>
#include <fstream>
#include <sstream>
#include <string>
#include <string_view>

namespace fs = std::filesystem;

#ifndef STURM_TRANSPILE_BIN
#  error "STURM_TRANSPILE_BIN must be defined by the CMake build (path to the sturm-transpile binary)."
#endif

// ── Test harness ──────────────────────────────────────────────────────────────
static int tests_run  = 0;
static int tests_pass = 0;

#define CHECK(cond) do {                                              \
    ++tests_run;                                                      \
    if (cond) { ++tests_pass; }                                       \
    else {                                                            \
        std::fprintf(stderr, "FAIL  %s:%d  %s\n",                     \
                     __FILE__, __LINE__, #cond);                      \
    }                                                                 \
} while (0)

// Run a shell command, return (exit_code, stdout+stderr).
static std::pair<int, std::string> run_cmd(const std::string& cmd) {
    std::string full = cmd + " 2>&1";
    FILE* pipe = ::popen(full.c_str(), "r");
    if (!pipe) return {-1, ""};
    std::string out;
    char buf[512];
    while (std::fgets(buf, sizeof(buf), pipe)) out += buf;
    int rc = ::pclose(pipe);
    // WEXITSTATUS is the right accessor, but plain rc is fine for
    // "zero vs non-zero" checks; we only inspect the sign below.
    if (WIFEXITED(rc)) return {WEXITSTATUS(rc), out};
    return {rc, out};
}

static std::string read_file_contents(const fs::path& p) {
    std::ifstream in(p, std::ios::binary);
    std::ostringstream oss;
    oss << in.rdbuf();
    return oss.str();
}

static fs::path make_scratch_dir(const char* tag) {
    fs::path base = fs::temp_directory_path() / "sturm-m4-driver-tests";
    fs::create_directories(base);
    fs::path dir = base / tag;
    fs::remove_all(dir);
    fs::create_directories(dir);
    return dir;
}

static fs::path quote(const fs::path& p) {
    // shell-quote a path by wrapping it in single quotes. The paths we use
    // are all under /tmp and never contain single quotes, so naïve wrapping
    // is safe here.
    return fs::path("'" + p.string() + "'");
}

// ── Tests ─────────────────────────────────────────────────────────────────────

static void test_version_flag_exits_zero() {
    std::string bin = STURM_TRANSPILE_BIN;
    auto [rc, out] = run_cmd(bin + " --version");
    CHECK(rc == 0);
    // Must mention "sturm-transpile" somewhere so users know which tool
    // they're querying.
    CHECK(out.find("sturm-transpile") != std::string::npos);
}

static void test_plain_source_gets_header() {
    // A plain C++ file with no quantum ops still runs the pipeline. The
    // matcher finds nothing, synthesize returns an empty list, and the
    // emitter writes <outdir>/<relpath> with the AUTO-GENERATED header
    // prepended but the body verbatim.
    fs::path dir = make_scratch_dir("plain");
    fs::path input  = dir / "hello.cpp";
    fs::path outdir = dir / "gen";
    fs::create_directories(outdir);

    const std::string payload =
        "// a tiny hello world -- no quantum types, just plain C++.\n"
        "int main() { return 0; }\n";
    {
        std::ofstream o(input, std::ios::binary);
        o << payload;
    }

    std::string cmd = std::string(STURM_TRANSPILE_BIN) +
        " " + quote(input).string() +
        " --output-dir " + quote(outdir).string();
    auto [rc, out] = run_cmd(cmd);
    if (rc != 0) std::fprintf(stderr, "driver stderr:\n%s\n", out.c_str());
    CHECK(rc == 0);

    fs::path expected = outdir / "hello.cpp";
    CHECK(fs::exists(expected));
    std::string got = read_file_contents(expected);
    // Header prepended at the top.
    CHECK(got.find("// AUTO-GENERATED by sturm-transpile") == 0);
    // Original payload preserved somewhere in the body.
    CHECK(got.find(payload) != std::string::npos);
}

static void test_already_generated_passes_through_verbatim() {
    // PRD AC #5: running the transpiler on its own output produces a
    // byte-identical file. We simulate this by writing a "pre-generated"
    // file containing the AUTO-GENERATED sentinel and verifying the
    // driver does not modify it.
    fs::path dir = make_scratch_dir("idempotent_driver");
    fs::path input  = dir / "already.cpp";
    fs::path outdir = dir / "gen";
    fs::create_directories(outdir);

    const std::string payload =
        "// AUTO-GENERATED by sturm-transpile -- do not edit\n"
        "// Source: already.cpp\n"
        "int main() { return 0; }\n";
    {
        std::ofstream o(input, std::ios::binary);
        o << payload;
    }

    std::string cmd = std::string(STURM_TRANSPILE_BIN) +
        " " + quote(input).string() +
        " --output-dir " + quote(outdir).string();
    auto [rc, out] = run_cmd(cmd);
    if (rc != 0) std::fprintf(stderr, "driver stderr:\n%s\n", out.c_str());
    CHECK(rc == 0);

    fs::path expected = outdir / "already.cpp";
    CHECK(fs::exists(expected));
    CHECK(read_file_contents(expected) == payload);
}

static void test_skip_marker_passes_through_verbatim() {
    // PRD AC #6: "// sturm-transpile: skip" magic comment suppresses the
    // pipeline, even when the body contains something the matcher would
    // otherwise act on.
    fs::path dir = make_scratch_dir("skip_marker");
    fs::path input  = dir / "skipme.cpp";
    fs::path outdir = dir / "gen";
    fs::create_directories(outdir);

    const std::string payload =
        "// sturm-transpile: skip\n"
        "// this file is user-managed; do not transpile.\n"
        "int main() { return 0; }\n";
    {
        std::ofstream o(input, std::ios::binary);
        o << payload;
    }

    std::string cmd = std::string(STURM_TRANSPILE_BIN) +
        " " + quote(input).string() +
        " --output-dir " + quote(outdir).string();
    auto [rc, out] = run_cmd(cmd);
    if (rc != 0) std::fprintf(stderr, "driver stderr:\n%s\n", out.c_str());
    CHECK(rc == 0);

    fs::path expected = outdir / "skipme.cpp";
    CHECK(fs::exists(expected));
    CHECK(read_file_contents(expected) == payload);
}

static void test_missing_input_exits_nonzero() {
    fs::path dir = make_scratch_dir("missing");
    fs::path input  = dir / "does_not_exist.cpp";
    fs::path outdir = dir / "gen";
    fs::create_directories(outdir);

    std::string cmd = std::string(STURM_TRANSPILE_BIN) +
        " " + quote(input).string() +
        " --output-dir " + quote(outdir).string();
    auto [rc, out] = run_cmd(cmd);
    CHECK(rc != 0);
}

static void test_nested_relative_input_mirrors_tree() {
    // Mirroring the source subtree under the output dir is part of the
    // driver contract (resolve_output_path). Cover it end-to-end. The
    // transpiler still prepends its header for non-skip inputs, so we
    // assert structure rather than byte equality here.
    fs::path dir = make_scratch_dir("nested");
    fs::path sub = dir / "src" / "sub";
    fs::create_directories(sub);
    fs::path input = sub / "nested.cpp";
    const std::string payload = "int f() { return 42; }\n";
    {
        std::ofstream o(input, std::ios::binary);
        o << payload;
    }
    fs::path outdir = dir / "gen";
    fs::create_directories(outdir);

    // Run from `dir` so the input can be referenced as a relative path.
    std::string cmd =
        "cd " + quote(dir).string() + " && " +
        std::string(STURM_TRANSPILE_BIN) +
        " src/sub/nested.cpp " +
        "--output-dir " + quote(outdir).string();
    auto [rc, out] = run_cmd(cmd);
    if (rc != 0) std::fprintf(stderr, "driver stderr:\n%s\n", out.c_str());
    CHECK(rc == 0);

    fs::path expected = outdir / "src" / "sub" / "nested.cpp";
    CHECK(fs::exists(expected));
    std::string got = read_file_contents(expected);
    // Either the file was transpiled (header + body) or passed through
    // verbatim; the body must at least contain the original source.
    CHECK(got.find(payload) != std::string::npos);
}

static void test_pj1f_wires_ccnot_fuse_matcher() {
    // Phase J PJ-1f: the zero-ancilla fusion peephole matcher must be
    // wired into main.cpp's TranspileConsumer BEFORE register_xor_assign
    // / register_compound_qbool / register_outer_var_guard. This driver-
    // level test verifies the wiring end-to-end: feed the canonical
    // fuse pair `qbool __t = a & b; x ^= __t;` through the real binary
    // and assert the output contains a `ccnot_inplace(x, a, b);` call
    // — the PJ-1d replacement text the peephole emits in place of the
    // original VarDecl + `^=` pair. If the matcher is not wired in, the
    // fixture falls through to the Phase A XOR_ASSIGN matcher, the
    // output omits the `ccnot_inplace(` identifier, and this test
    // fails loudly.
    fs::path dir = make_scratch_dir("pj1f_ccnot_fuse");
    fs::path input  = dir / "fuse_pair.cpp";
    fs::path outdir = dir / "gen";
    fs::create_directories(outdir);

    // Minimal in-file qbool stub — mirrors the or_single fixture shape
    // so the MVP FixedCompilationDatabase (no external includes) can
    // still parse and type-check.
    const std::string payload =
        "namespace sturm {\n"
        "class qbool {\n"
        "public:\n"
        "    qbool() {}\n"
        "    qbool(const qbool&) {}\n"
        "    qbool& operator=(const qbool&) { return *this; }\n"
        "    qbool& operator^=(const qbool&) { return *this; }\n"
        "};\n"
        "inline qbool operator&(const qbool&, const qbool&) "
        "{ return qbool{}; }\n"
        "} // namespace sturm\n"
        "using sturm::qbool;\n"
        "\n"
        "void demo(qbool a, qbool b, qbool x) {\n"
        "    qbool tmp = a & b;\n"
        "    x ^= tmp;\n"
        "}\n";
    {
        std::ofstream o(input, std::ios::binary);
        o << payload;
    }

    std::string cmd = std::string(STURM_TRANSPILE_BIN) +
        " " + quote(input).string() +
        " --output-dir " + quote(outdir).string();
    auto [rc, out] = run_cmd(cmd);
    if (rc != 0) std::fprintf(stderr, "driver stderr:\n%s\n", out.c_str());
    CHECK(rc == 0);

    fs::path expected = outdir / "fuse_pair.cpp";
    CHECK(fs::exists(expected));
    std::string got = read_file_contents(expected);

    // The PJ-1d matcher's replacement text fires TWICE in the output:
    // once as the forward emission (QReplacement over the original two
    // statements) and once as the uncompute emission (CCX is self-
    // adjoint per PJ-1c). Both share the identifier `ccnot_inplace(`.
    // Finding at least one occurrence proves the matcher is wired in;
    // the full two-occurrence contract is pinned by the unit tests in
    // test_matcher_ccnot_fuse.cpp.
    CHECK(got.find("ccnot_inplace(x, a, b)") != std::string::npos);
    // The fused output must NOT still contain the original
    // `qbool tmp = a & b;` VarDecl — the QReplacement covers it. If
    // the matcher fails to wire in, the replacement never lands and
    // the original VarDecl survives in the output.
    CHECK(got.find("qbool tmp = a & b;") == std::string::npos);
}

static void test_pj4b_wires_dead_ancilla_matcher() {
    // Phase J PJ-4b: the dead-ancilla elimination matcher must be wired
    // into main.cpp's TranspileConsumer BEFORE the MVP OR matcher,
    // BEFORE the Phase A bitwise matchers (NOT / XOR / XOR_ASSIGN), and
    // BEFORE the Phase E compound_qbool matcher. This driver-level test
    // verifies the wiring end-to-end: feed a canonical zero-reader
    // `qbool t = a | b;` fixture through the real binary and assert
    // that
    //
    //   - the output does NOT retain the original
    //     `qbool t = a | b;` VarDecl (PJ-4a's QReplacement deletes it).
    //   - the output does NOT emit any `uncompute_or(t, a, b);` line
    //     (the OR matcher would have pushed a QOperation had PJ-4a not
    //     been wired in ahead of it, resulting in a stale uncompute
    //     against the deleted decl).
    //
    // If the matcher is not wired in, PJ-4a never fires, the original
    // VarDecl survives AND the OR matcher emits an `uncompute_or(...)`
    // line referencing the deleted `t`. Either mismatch fails the test.
    fs::path dir = make_scratch_dir("pj4b_dead_ancilla");
    fs::path input  = dir / "dead_or.cpp";
    fs::path outdir = dir / "gen";
    fs::create_directories(outdir);

    // Minimal in-file qbool stub — mirrors the PJ-1f fuse_pair fixture
    // so the MVP FixedCompilationDatabase (no external includes) can
    // still parse and type-check.
    const std::string payload =
        "namespace sturm {\n"
        "class qbool {\n"
        "public:\n"
        "    qbool() {}\n"
        "    qbool(const qbool&) {}\n"
        "    qbool& operator=(const qbool&) { return *this; }\n"
        "};\n"
        "inline qbool operator|(const qbool&, const qbool&) "
        "{ return qbool{}; }\n"
        "} // namespace sturm\n"
        "using sturm::qbool;\n"
        "\n"
        "void demo(qbool a, qbool b) {\n"
        "    qbool t = a | b;\n"
        "}\n";
    {
        std::ofstream o(input, std::ios::binary);
        o << payload;
    }

    std::string cmd = std::string(STURM_TRANSPILE_BIN) +
        " " + quote(input).string() +
        " --output-dir " + quote(outdir).string();
    auto [rc, out] = run_cmd(cmd);
    if (rc != 0) std::fprintf(stderr, "driver stderr:\n%s\n", out.c_str());
    CHECK(rc == 0);

    fs::path expected = outdir / "dead_or.cpp";
    CHECK(fs::exists(expected));
    std::string got = read_file_contents(expected);

    // The dead-ancilla eliminator's empty-text QReplacement drops the
    // original VarDecl verbatim — the output must not retain it. If
    // the matcher is not wired in, the VarDecl survives and this
    // assertion fails loudly.
    CHECK(got.find("qbool t = a | b;") == std::string::npos);
    // No `uncompute_or(` must appear in the output. If PJ-4a was NOT
    // registered before the MVP OR matcher, the OR matcher's
    // QOperation would survive the pipeline AND the M8 pass would
    // render an `uncompute_or(t, a, b);` line — against a `t` the
    // eliminator has already deleted. The pipeline guards against
    // this via `eliminated_stmt_ranges` + `apply_eliminated_stmt_guards`
    // which the wiring must invoke post-matchAST.
    CHECK(got.find("uncompute_or(") == std::string::npos);
}

static void test_pj3e_wires_hoist_invariant_matcher() {
    // Phase J PJ-3e: the uncompute-hoisting matcher must be wired into
    // main.cpp's TranspileConsumer LAST — after every Phase A..I per-op
    // matcher, after the PJ-1f CCX-fuse peephole, and after the PJ-4b
    // dead-ancilla eliminator. This driver-level test verifies the
    // wiring end-to-end: feed a canonical loop-invariant fixture
    // (`qbool t = a | b;` inside a for-loop body over outer parameters
    // `a`, `b` that are never written in the body) through the real
    // binary and assert:
    //
    //   1. The output contains the `uncompute_or(t, a, b);` call — the
    //      MVP OR matcher fires on the VarDecl AND the op survives the
    //      M8 pass.
    //   2. The `uncompute_or(...)` line lands AFTER the loop's closing
    //      brace, NOT inside the loop body. This is the load-bearing
    //      semantic: `hoist_to_override` (set by the PJ-3d callback
    //      only if wired in) takes precedence over `scope.close_brace`
    //      inside uncompute_pass.cpp's anchor-selection ladder, moving
    //      the uncompute out of the loop body to the loop-enclosing
    //      scope's close brace.
    //
    // If the matcher is NOT wired in, the PJ-3d callback never fires,
    // `hoist_to_override` stays invalid, and the uncompute lands at
    // `scope.close_brace` — i.e. INSIDE the loop body, just before its
    // `}`. The ordering assertion below catches that regression loudly.
    fs::path dir = make_scratch_dir("pj3e_hoist_invariant");
    fs::path input  = dir / "hoist_or.cpp";
    fs::path outdir = dir / "gen";
    fs::create_directories(outdir);

    // Minimal in-file qbool stub — mirrors the PJ-1f / PJ-4b fixtures so
    // the MVP FixedCompilationDatabase (no external includes) can still
    // parse and type-check. We add a trailing `(void)t;` reader so PJ-4a
    // does not eliminate the decl (zero-reader would trigger elimination
    // BEFORE the hoist matcher runs, suppressing the op entirely).
    const std::string payload =
        "namespace sturm {\n"
        "class qbool {\n"
        "public:\n"
        "    qbool() {}\n"
        "    qbool(const qbool&) {}\n"
        "    qbool& operator=(const qbool&) { return *this; }\n"
        "};\n"
        "inline qbool operator|(const qbool&, const qbool&) "
        "{ return qbool{}; }\n"
        "} // namespace sturm\n"
        "using sturm::qbool;\n"
        "\n"
        "void demo(qbool a, qbool b) {\n"
        "    for (int i = 0; i < 3; ++i) {\n"
        "        qbool t = a | b;\n"
        "        (void)t;\n"
        "    }\n"
        "}\n";
    {
        std::ofstream o(input, std::ios::binary);
        o << payload;
    }

    std::string cmd = std::string(STURM_TRANSPILE_BIN) +
        " " + quote(input).string() +
        " --output-dir " + quote(outdir).string();
    auto [rc, out] = run_cmd(cmd);
    if (rc != 0) std::fprintf(stderr, "driver stderr:\n%s\n", out.c_str());
    CHECK(rc == 0);

    fs::path expected = outdir / "hoist_or.cpp";
    CHECK(fs::exists(expected));
    std::string got = read_file_contents(expected);

    // (1) The MVP OR matcher fires; the M8 pass renders an uncompute.
    const std::string uncompute_call = "uncompute_or(t, a, b);";
    const std::size_t uncompute_pos = got.find(uncompute_call);
    CHECK(uncompute_pos != std::string::npos);

    // (2) The uncompute lands OUTSIDE the for-loop body. The loop body
    // `(void)t;` is the last statement inside the `{ ... }`; the
    // closing `}` is where the scope-level uncompute would be emitted
    // absent PJ-3d. With PJ-3d wired in, `hoist_to_override` points at
    // the FUNCTION-BODY close brace (one level up), so the uncompute
    // sits AFTER the loop's `}` not before it.
    //
    // A robust probe: locate the loop body close brace — the first `}`
    // after `(void)t;` — and assert the uncompute call comes AFTER it.
    const std::size_t void_pos = got.find("(void)t;");
    CHECK(void_pos != std::string::npos);
    const std::size_t loop_close_brace_pos = got.find('}', void_pos);
    CHECK(loop_close_brace_pos != std::string::npos);
    CHECK(uncompute_pos > loop_close_brace_pos);
}

// ── PM1-6 tests: --dump-transpiled / -d <path> ──────────────────────────────

static void test_pm1_6_dump_transpiled_writes_to_exact_path() {
    // PM1-6: `--dump-transpiled=<path>` writes the rewritten buffer
    // (header + body) to that EXACT path, bypassing
    // resolve_output_path(). `--output-dir` is optional in this mode.
    fs::path dir = make_scratch_dir("pm1_6_dump_long");
    fs::path input = dir / "hello.cpp";
    const std::string payload =
        "// a tiny hello world -- no quantum types, just plain C++.\n"
        "int main() { return 0; }\n";
    {
        std::ofstream o(input, std::ios::binary);
        o << payload;
    }

    // Intentionally put the dump path in a DIFFERENT subdirectory to
    // prove resolve_output_path() is NOT being applied. The transpiler
    // must create the parent dir (write_file does mkdir -p).
    fs::path dump = dir / "out" / "renamed.transpiled.cpp";

    std::string cmd = std::string(STURM_TRANSPILE_BIN) +
        " " + quote(input).string() +
        " --dump-transpiled=" + quote(dump).string();
    auto [rc, out] = run_cmd(cmd);
    if (rc != 0) std::fprintf(stderr, "driver stderr:\n%s\n", out.c_str());
    CHECK(rc == 0);

    CHECK(fs::exists(dump));
    std::string got = read_file_contents(dump);
    // Output must carry the M5 idempotency header.
    CHECK(got.find("// AUTO-GENERATED by sturm-transpile") == 0);
    // Original source body preserved somewhere.
    CHECK(got.find(payload) != std::string::npos);
}

static void test_pm1_6_dump_transpiled_short_alias_d() {
    // PM1-6 accepts the `-d <path>` short form in addition to
    // `--dump-transpiled=<path>`. Same semantics.
    fs::path dir = make_scratch_dir("pm1_6_dump_short");
    fs::path input = dir / "hello.cpp";
    {
        std::ofstream o(input, std::ios::binary);
        o << "int main() { return 0; }\n";
    }
    fs::path dump = dir / "out.cpp";

    // `-d=<path>` is the cl::opt spelling most robust to argv parsing
    // across llvm versions.
    std::string cmd = std::string(STURM_TRANSPILE_BIN) +
        " " + quote(input).string() +
        " -d=" + quote(dump).string();
    auto [rc, out] = run_cmd(cmd);
    if (rc != 0) std::fprintf(stderr, "driver stderr:\n%s\n", out.c_str());
    CHECK(rc == 0);
    CHECK(fs::exists(dump));
    std::string got = read_file_contents(dump);
    CHECK(got.find("// AUTO-GENERATED by sturm-transpile") == 0);
}

static void test_pm1_6_dump_matches_output_dir_byte_for_byte() {
    // PM1-6 gate: output matches the legacy standalone invocation
    // BYTE-FOR-BYTE. Run the transpiler twice on identical input — once
    // via --output-dir, once via --dump-transpiled — and compare bytes.
    fs::path dir = make_scratch_dir("pm1_6_byte_match");
    fs::path input = dir / "demo.cpp";

    // Use a Sturm-like fixture body so the pipeline actually rewrites
    // something (not strictly required for byte-match, but makes the
    // test more meaningful).
    const std::string payload =
        "namespace sturm {\n"
        "class qbool {\n"
        "public:\n"
        "    qbool() {}\n"
        "    qbool(const qbool&) {}\n"
        "    qbool& operator=(const qbool&) { return *this; }\n"
        "};\n"
        "inline qbool operator|(const qbool&, const qbool&) "
        "{ return qbool{}; }\n"
        "} // namespace sturm\n"
        "using sturm::qbool;\n"
        "\n"
        "void demo(qbool a, qbool b) {\n"
        "    qbool t = a | b;\n"
        "    (void)t;\n"
        "}\n";
    {
        std::ofstream o(input, std::ios::binary);
        o << payload;
    }

    // Leg 1: legacy --output-dir.
    fs::path outdir = dir / "gen";
    fs::create_directories(outdir);
    std::string cmd_legacy = std::string(STURM_TRANSPILE_BIN) +
        " " + quote(input).string() +
        " --output-dir " + quote(outdir).string();
    auto r1 = run_cmd(cmd_legacy);
    if (r1.first != 0) std::fprintf(stderr, "legacy driver stderr:\n%s\n",
                                    r1.second.c_str());
    CHECK(r1.first == 0);
    fs::path legacy_out = outdir / "demo.cpp";
    CHECK(fs::exists(legacy_out));
    std::string legacy_bytes = read_file_contents(legacy_out);

    // Leg 2: --dump-transpiled to a different path.
    fs::path dump = dir / "dumped.cpp";
    std::string cmd_dump = std::string(STURM_TRANSPILE_BIN) +
        " " + quote(input).string() +
        " --dump-transpiled=" + quote(dump).string();
    auto r2 = run_cmd(cmd_dump);
    if (r2.first != 0) std::fprintf(stderr, "dump driver stderr:\n%s\n",
                                    r2.second.c_str());
    CHECK(r2.first == 0);
    CHECK(fs::exists(dump));
    std::string dump_bytes = read_file_contents(dump);

    // Byte-for-byte equality.
    CHECK(legacy_bytes == dump_bytes);
}

static void test_pm1_6_requires_one_of_outdir_or_dump() {
    // Without either flag the driver must fail.  Positional input alone
    // would have nowhere to write.
    fs::path dir = make_scratch_dir("pm1_6_neither_flag");
    fs::path input = dir / "orphan.cpp";
    {
        std::ofstream o(input, std::ios::binary);
        o << "int main() { return 0; }\n";
    }
    std::string cmd = std::string(STURM_TRANSPILE_BIN) +
        " " + quote(input).string();
    auto [rc, out] = run_cmd(cmd);
    CHECK(rc != 0);
}

static void test_pm1_6_skip_marker_honored_under_dump() {
    // PRD AC #6 still holds under --dump-transpiled: a skipped file is
    // copied BYTE-IDENTICAL to the dump destination. The idempotency
    // header is NOT prepended — the input already carries its own
    // shape, and the verbatim contract is preserved.
    fs::path dir = make_scratch_dir("pm1_6_dump_skip");
    fs::path input = dir / "skipme.cpp";
    const std::string payload =
        "// sturm-transpile: skip\n"
        "int main() { return 0; }\n";
    {
        std::ofstream o(input, std::ios::binary);
        o << payload;
    }
    fs::path dump = dir / "out.cpp";

    std::string cmd = std::string(STURM_TRANSPILE_BIN) +
        " " + quote(input).string() +
        " --dump-transpiled=" + quote(dump).string();
    auto [rc, out] = run_cmd(cmd);
    if (rc != 0) std::fprintf(stderr, "driver stderr:\n%s\n", out.c_str());
    CHECK(rc == 0);
    CHECK(fs::exists(dump));
    // Byte-identical to the input.
    CHECK(read_file_contents(dump) == payload);
}

int main() {
    test_version_flag_exits_zero();
    test_plain_source_gets_header();
    test_already_generated_passes_through_verbatim();
    test_skip_marker_passes_through_verbatim();
    test_missing_input_exits_nonzero();
    test_nested_relative_input_mirrors_tree();
    test_pj1f_wires_ccnot_fuse_matcher();
    test_pj4b_wires_dead_ancilla_matcher();
    test_pj3e_wires_hoist_invariant_matcher();
    test_pm1_6_dump_transpiled_writes_to_exact_path();
    test_pm1_6_dump_transpiled_short_alias_d();
    test_pm1_6_dump_matches_output_dir_byte_for_byte();
    test_pm1_6_requires_one_of_outdir_or_dump();
    test_pm1_6_skip_marker_honored_under_dump();

    std::printf("PASS: %d/%d\n", tests_pass, tests_run);
    return tests_pass == tests_run ? 0 : 1;
}
